<script setup lang="ts">
import { useDemoStore } from '~/stores/demo'
import { useSessionStore } from '~/stores/session'
definePageMeta({layout:'workspace'});const demo=useDemoStore(),session=useSessionStore();const showCreate=ref(false);const form=reactive({name:'',brandName:'',product:'',objective:''});const campaigns=computed(()=>demo.data.campaigns.filter((c:any)=>session.session?.role==='admin'||c.organizationId===session.session?.organizationId));function create(){if(demo.run({type:'campaign:create',...form},session.session||{})){showCreate.value=false;Object.assign(form,{name:'',brandName:'',product:'',objective:''})}}</script>
<template><div class="page-content"><div class="page-title-row"><div><span class="page-label">CAMPAIGN MATCHING</span><h1>Campaigns</h1><p>Match a creator to a clear brief using public channel evidence.</p></div><button v-if="session.session?.role==='agency'" class="button button-primary" @click="showCreate=true">＋ Create campaign</button></div><div class="campaign-grid"><article v-for="c in campaigns" :key="c.id" class="campaign-card"><span class="tag tag-violet">{{ c.brandName || 'CAMPAIGN BRIEF' }}</span><h2>{{ c.name }}</h2><p>{{ c.objective }}</p><div class="campaign-card-foot"><span class="secondary-text">{{ c.fitResults?.length || 0 }} creator fits saved</span><NuxtLink :to="`/app/campaigns/${c.id}`" class="button button-outline button-small">Open campaign →</NuxtLink></div></article><div v-if="!campaigns.length" class="panel empty-state">No campaign is available in this role's workspace.</div></div><div v-if="showCreate" class="modal-backdrop" @click.self="showCreate=false"><section class="modal-card"><div class="modal-head"><div><span class="page-label">NEW CAMPAIGN</span><h2>Create a short campaign brief</h2></div><button class="modal-close" aria-label="Close" @click="showCreate=false">×</button></div><form class="form-stack" @submit.prevent="create"><label class="form-field">Campaign name<input v-model="form.name" required minlength="3"></label><label class="form-field">Brand / product<input v-model="form.brandName"></label><label class="form-field">Product<input v-model="form.product"></label><label class="form-field">Creator brief<textarea v-model="form.objective" required minlength="12" placeholder="Describe the story and type of creator you are looking for."></textarea></label><button class="button button-primary">Save campaign</button></form></section></div></div></template>
